export const sha=bytes=>createHash('sha256').update(bytes).digest('hex');
export const stable=value=>JSON.stringify(sort(value));
function sort(value){return Array.isArray(value)?value.map(sort):value&&typeof value==='object'?Object.fromEntries(Object.keys(value).sort().map(key=>[key,sort(value[key])])):value;}
export const digest=value=>sha(stable(value));
export const absolute=relative=>path.isAbsolute(relative)?relative:path.join(sourceRoot,relative);
export const json=async relative=>JSON.parse(await readFile(absolute(relative),'utf8'));
export async function optional(file){try{return await readFile(file);}catch(error){if(error.code==='ENOENT')return null;throw error;}}
export async function hashOptional(file){const bytes=await optional(file);return bytes===null?null:sha(bytes);}
async function referenceBytes(relative){const file=absolute(relative),stat=await lstat(file);assert(stat.isFile()&&!stat.isSymbolicLink(),`Regular file required: ${relative}`);return readFile(file);}
export async function reference(relative){const bytes=await referenceBytes(relative);return {path:relative,bytes:bytes.length,sha256:sha(bytes)};}
export async function authenticate(ref){assert(ref&&typeof ref.path==='string');const bytes=await referenceBytes(ref.path);assert.deepEqual({path:ref.path,bytes:bytes.length,sha256:sha(bytes)},ref,`Reference changed: ${ref.path}`);return bytes;}
