// This one historical reference resolves to its authenticated immutable prefix.
// authenticate() retains exact path/byte semantics for every ordinary reference.
export async function verifyLiveSessionPrefixSuccession(deps={}){
 const auth=deps.authenticate??authenticate,read=async ref=>{const bytes=await auth(ref);assert.equal(bytes.length,ref.bytes,'Session prefix byte count changed');assert.equal(sha(bytes),ref.sha256,'Session prefix bytes changed');return bytes;};
 const proof=JSON.parse(await read(liveSessionPrefixPin));exactKeys(proof,['version','kind','original','archive','observedSnapshot','appended','claims'],'Live session prefix proof');assert.equal(proof.version,1);assert.equal(proof.kind,'rollout004-authenticated-live-session-prefix-succession');assert.deepEqual(proof.original,liveSessionOriginalPin);
 assert.deepEqual(proof.archive,{...liveSessionOriginalPin,path:`${directory}/live-session-original-prefix.jsonl`});assert.equal(proof.observedSnapshot.path,`${directory}/live-session-observed-append.jsonl`);
 const prefix=await read(proof.archive),observed=await read(proof.observedSnapshot);assert(observed.length>prefix.length);assert(prefix.equals(observed.subarray(0,prefix.length)),'Observed session prefix changed');
 const appended=observed.subarray(prefix.length);exactKeys(proof.appended,['bytes','sha256','types'],'Live session appended metadata');assert.equal(appended.length,proof.appended.bytes);assert.equal(sha(appended),proof.appended.sha256);assert.deepEqual(proof.appended.types,['event_msg:thread_settings_applied']);
 const events=appended.toString('utf8').trim().split('\n').map(JSON.parse);assert(events.length>0);for(const event of events)assert.equal(`${event.type}:${event.payload?.type}`,'event_msg:thread_settings_applied','Appended session material grants no authority');
 return {original:proof.original,archive:proof.archive};
}
