export async function verifyBridge(){
  const bridge=JSON.parse(await authenticate(bridgePin));assert.equal(bridge.kind,'completed-native-hook-v2-live-004-historical-authority-bridge');assert.equal(bridge.gateResult.pass,true);
  const historical=new Map(bridge.historicalMappings.map(item=>[digest(item.original),item.archive]));
  const prefix=await verifyLiveSessionPrefixSuccession();assert(bridge.externalReferences.some(ref=>digest(ref)===digest(prefix.original)),'Historical session pin absent');assert(!historical.has(digest(prefix.original)),'Historical session mapping already exists');historical.set(digest(prefix.original),prefix.archive);
  for(const ref of [...bridge.references,...bridge.externalReferences])await authenticate(historical.get(digest(ref))??ref);
  for(const mapping of bridge.historicalMappings){assert.equal(mapping.original.bytes,mapping.archive.bytes);assert.equal(mapping.original.sha256,mapping.archive.sha256);await authenticate(mapping.archive);}
  for(const name of ['liveReceipt','liveBefore','nativeReport','currentFreezeV3']){const item=bridge.authorityRecords[name];assert.deepEqual(JSON.parse(await authenticate(item.reference)),item.record);}
  await authenticate(bridge.gate);await authenticate(sourceAuthorityPin);await authenticate(sourceGatePin);await authenticate(originalBaselinePin);
  for(const ref of bridge.currentHelpers)await authenticate(ref);
  const live=(await json('.harness/features.json')).features.find(item=>item.id==='native-hook-v2-live-004');assert(live);assert.deepEqual({status:live.status,attempts:live.attempts,contract:live.contract,evidence:live.evidence}, {...bridge.finalLive,evidence:bridge.finalLive.evidence.map(ref=>ref.path)},'Successful LIVE projection changed');
  for(const ref of bridge.finalLive.evidence)await authenticate(ref);
  const node=await nodeIdentity();assert.equal(node.executableSha256,bridge.bindings.node.executableSha256);assert.equal(node.version,bridge.bindings.node.version);
  assert.deepEqual(bridge.futureGrant.paths,helpers);assert.equal(bridge.futureGrant.requireExactAdditions,true);
  return bridge;
}
