export function configWithoutPolicies(config){const result=structuredClone(config);delete result.policies.maxAttempts;delete result.policies.maxRepeatedFailures;return result;}
export function assertConfigDelta(before,after){const normalized=configWithoutPolicies(after);if(!Object.hasOwn(before.context??{},'codexCodeModeResultSuppressionConfirmed')&&normalized.context?.codexCodeModeResultSuppressionConfirmed===false)delete normalized.context.codexCodeModeResultSuppressionConfirmed;assert.deepEqual(normalized,configWithoutPolicies(before),'Unexpected config migration');return {policy:{maxAttempts:after.policies.maxAttempts,maxRepeatedFailures:after.policies.maxRepeatedFailures},defaultAdded:!Object.hasOwn(before.context??{},'codexCodeModeResultSuppressionConfirmed')&&Object.hasOwn(after.context??{},'codexCodeModeResultSuppressionConfirmed')};}
export function contractProjection(feature){return Object.fromEntries(Object.entries(feature).filter(([key])=>!['status','attempts','repeatedFailures','blocker','lastFailure','lastFailureSignature','evidence','updatedAt'].includes(key)));}
export async function tree(root,relative){const result={};async function walk(rel){let stat;try{stat=await lstat(path.join(root,rel));}catch(error){if(error.code==='ENOENT')return;throw error;}assert(!stat.isSymbolicLink(),`Symlink refused: ${rel}`);if(stat.isDirectory()){for(const name of (await readdir(path.join(root,rel))).sort())await walk(`${rel}/${name}`);}else{assert(stat.isFile());result[rel]=await hashOptional(path.join(root,rel));}}await walk(relative);return result;}
export const historyTrees=['history','evidence','baselines','handoffs','worker-capsules'];
export async function preservation(root){const config=JSON.parse(await readFile(path.join(root,'.harness/config.json'),'utf8'));const features=JSON.parse(await readFile(path.join(root,'.harness/features.json'),'utf8'));const continuity=JSON.parse(await readFile(path.join(root,'.harness/continuity.json'),'utf8'));const events=await optional(path.join(root,'.harness/events.jsonl'))??Buffer.alloc(0);const histories=Object.assign({},...await Promise.all(historyTrees.map(name=>tree(root,`.harness/${name}`))));const selected={};for(const name of ['.harness/progress.md','.harness/handoff.md','.claude/settings.local.json'])selected[name]=await hashOptional(path.join(root,name));return {root,config,features,continuity,events:{bytes:events.length,sha256:sha(events)},histories,selected};}
